// MARK: - Firestore paths

/// Document and collection paths (FSD §6).
public enum TMLPaths {
    /// `users/{userId}`
    public static func user(userId: String) -> String { "users/\(userId)" }
    /// The collection holding `users/{userId}`.
    public static func userCollection() -> String { "users" }
    /// `users/{userId}/devices/{deviceId}`
    public static func device(userId: String, deviceId: String) -> String { "users/\(userId)/devices/\(deviceId)" }
    /// The collection holding `users/{userId}/devices/{deviceId}`.
    public static func deviceCollection(userId: String) -> String { "users/\(userId)/devices" }
    /// `users/{userId}/trustedContacts/{contactId}`
    public static func trustedContact(userId: String, contactId: String) -> String { "users/\(userId)/trustedContacts/\(contactId)" }
    /// The collection holding `users/{userId}/trustedContacts/{contactId}`.
    public static func trustedContactCollection(userId: String) -> String { "users/\(userId)/trustedContacts" }
    /// `shareSessions/{sessionId}`
    public static func shareSession(sessionId: String) -> String { "shareSessions/\(sessionId)" }
    /// The collection holding `shareSessions/{sessionId}`.
    public static func shareSessionCollection() -> String { "shareSessions" }
    /// `shareSessions/{sessionId}/private/meta`
    public static func sessionPrivateMeta(sessionId: String) -> String { "shareSessions/\(sessionId)/private/meta" }
    /// The collection holding `shareSessions/{sessionId}/private/meta`.
    public static func sessionPrivateMetaCollection(sessionId: String) -> String { "shareSessions/\(sessionId)/private" }
    /// `shareSessions/{sessionId}/pings/{pingId}`
    public static func ping(sessionId: String, pingId: String) -> String { "shareSessions/\(sessionId)/pings/\(pingId)" }
    /// The collection holding `shareSessions/{sessionId}/pings/{pingId}`.
    public static func pingCollection(sessionId: String) -> String { "shareSessions/\(sessionId)/pings" }
    /// `shareSessions/{sessionId}/viewerPings/{pingId}`
    public static func viewerPing(sessionId: String, pingId: String) -> String { "shareSessions/\(sessionId)/viewerPings/\(pingId)" }
    /// The collection holding `shareSessions/{sessionId}/viewerPings/{pingId}`.
    public static func viewerPingCollection(sessionId: String) -> String { "shareSessions/\(sessionId)/viewerPings" }
    /// `shareSessions/{sessionId}/viewerSignIns/{viewerUid}`
    public static func viewerSignIn(sessionId: String, viewerUid: String) -> String { "shareSessions/\(sessionId)/viewerSignIns/\(viewerUid)" }
    /// The collection holding `shareSessions/{sessionId}/viewerSignIns/{viewerUid}`.
    public static func viewerSignInCollection(sessionId: String) -> String { "shareSessions/\(sessionId)/viewerSignIns" }
    /// `mascots/{mascotId}`
    public static func mascot(mascotId: String) -> String { "mascots/\(mascotId)" }
    /// The collection holding `mascots/{mascotId}`.
    public static func mascotCollection() -> String { "mascots" }
    /// `callLogs/{callLogId}`
    public static func callLog(callLogId: String) -> String { "callLogs/\(callLogId)" }
    /// The collection holding `callLogs/{callLogId}`.
    public static func callLogCollection() -> String { "callLogs" }
}

// MARK: - Constants (FSD values)

public enum TMLSchemaConstants {
    /// Names are 1–24 grapheme clusters after trimming; typing stops at 24. (FSD §4 Sign up, Who it's for)
    public static let nameMaxLength = 24
    /// Hard limit: expires_at = started_at + 60 minutes. (FSD §4 Auto-expiry)
    public static let sessionLimitMinutes = 60
    /// Default timer without a call, or on Android without the Phone permission. (FSD §4 Stop rule)
    public static let defaultStopMinutes = 30
    /// createSession writes ping_interval_s = 5 until the app writes the interval in use. (FSD §4 Battery-aware pings; x-decisions Q-PING-INTERVAL-INIT)
    public static let initialPingIntervalSeconds = 5
    /// The quiet "Sharing stops at …" line appears 5 minutes before expires_at. (FSD §4 1-hour warning)
    public static let expiryWarningMinutes = 5
    /// The app refreshes last_ping_at at least every 30 seconds, even without a GPS fix. (FSD §6 Design decisions)
    public static let checkInIntervalSeconds = 30
    /// Viewer writes need last_ping_at under 2 minutes old. (FSD §6 Viewer access)
    public static let shareBackFreshnessSeconds = 120
    /// If the app is killed or offline for 2 minutes, a scheduled function clears call_active. (FSD §6 Design decisions)
    public static let watchdogTimeoutSeconds = 120
    /// With the call stop rule, the session stops 10 minutes after the watchdog clears call_active. (FSD §4 Auto-expiry, §9)
    public static let callStopGraceMinutes = 10
    /// Never fewer than 1 ping per 60 s while active. (FSD §4 Battery-aware pings, §7)
    public static let maxPingIntervalSeconds = 60
    /// From 20% to 10% battery. (FSD §4 Battery-aware pings)
    public static let pingIntervalLowBatterySeconds = 15
    /// Under 10% battery. (FSD §4 Battery-aware pings)
    public static let pingIntervalCriticalBatterySeconds = 60
    /// Above this, a ping every 3–5 s. (FSD §4 Battery-aware pings)
    public static let lowBatteryPercent = 20
    /// Under this, a ping every 60 s. (FSD §4 Battery-aware pings)
    public static let criticalBatteryPercent = 10
    /// A person shows as Live while their newest ping is under 3 ping intervals old… (FSD §7 Offline behavior)
    public static let liveStalePingIntervals = 3
    /// …and at least 15 s; then "Last seen". (FSD §7 Offline behavior)
    public static let liveStaleMinSeconds = 15
    /// The sharer's app shows No GPS signal after 30 s without a fix better than 100 m. (FSD §7 Offline behavior)
    public static let noFixTimeoutSeconds = 30
    /// A fix counts when it is better than 100 m. (FSD §7 Offline behavior)
    public static let noFixAccuracyMeters = 100
    /// Approximate rounds each point to about 500 m on the phone. (FSD §4 Location detail)
    public static let approximateRoundingMeters = 500
    /// Both maps show a soft circle 1 km across around the rounded point. (FSD §4 Location detail)
    public static let approximateCircleDiameterMeters = 1000
    /// pings and viewerPings are deleted 24 hours after the session ends. (FSD §6, §8 Retention)
    public static let pingRetentionHours = 24
    /// Session metadata and call logs are purged after 30 days. (FSD §8 Retention)
    public static let metadataRetentionDays = 30
    /// The text code has 6 digits. (FSD §4 Sign up)
    public static let otpLength = 6
    /// A new code can be sent after 30 seconds. (FSD §4 Sign up)
    public static let otpResendSeconds = 30
    /// The link token is 128 random bits… (FSD §6 Viewer access; x-decisions Q-TOKEN-HASH)
    public static let linkTokenBits = 128
    /// …in base64url without padding: 22 characters. (FSD §6 Viewer access; x-decisions Q-TOKEN-HASH)
    public static let linkTokenLength = 22
    /// redeemLinkToken mints at most 10 browser sign-ins per session (viewer plus watchers, counted from viewerSignIns). A new browser past that gets resource-exhausted {reason: 'too_many_viewers'}; a browser that already has a sign-in can still refresh. (FSD §6 Viewer access; lead decision Oct 18 (abuse cap))
    public static let maxViewerSignIns = 10
    /// Share links are <viewer origin>/s/<token>; the apps never claim this path for universal links or App Links. (FSD §4 Live map link; x-decisions Q-LINK-FORMAT)
    public static let shareLinkPath = "/s/"
}

// MARK: - Mascot catalog

public struct TMLMascotCatalogEntry: Hashable, Sendable {
    public let id: TMLMascotId
    public let set: TMLMascotSet
    public let accessories: [TMLMascotAccessory]
}

/// The v1 mascot library (FSD §11), for seeding mascots/{id} and for the pickers. Accessory support matches mascots/model/accessories.mjs ACCESSORY_SUPPORT and the prototype's ACC_FOR.
public enum TMLMascotCatalog {
    public static let all: [TMLMascotCatalogEntry] = [
        TMLMascotCatalogEntry(id: .fox, set: .classics, accessories: [.headphones, .glasses, .headlamp]),
        TMLMascotCatalogEntry(id: .ghost, set: .classics, accessories: [.headphones, .glasses, .headlamp]),
        TMLMascotCatalogEntry(id: .robot, set: .classics, accessories: [.headlamp]),
        TMLMascotCatalogEntry(id: .astronaut, set: .classics, accessories: []),
        TMLMascotCatalogEntry(id: .hero, set: .anime, accessories: [.glasses]),
        TMLMascotCatalogEntry(id: .star, set: .anime, accessories: [.headphones, .glasses, .headlamp]),
        TMLMascotCatalogEntry(id: .ninja, set: .anime, accessories: [.headphones]),
        TMLMascotCatalogEntry(id: .neko, set: .anime, accessories: [.glasses, .headlamp]),
        TMLMascotCatalogEntry(id: .ace, set: .movie, accessories: [.headphones, .headlamp]),
        TMLMascotCatalogEntry(id: .detective, set: .movie, accessories: [.glasses]),
        TMLMascotCatalogEntry(id: .cowboy, set: .movie, accessories: [.glasses]),
        TMLMascotCatalogEntry(id: .agent, set: .movie, accessories: [.headphones, .glasses, .headlamp]),
    ]
    public static let defaultMascot: TMLMascotId = .fox
    public static let defaultColor: TMLMascotColor = .original

    /// The accessories a mascot takes.
    public static func accessories(for id: TMLMascotId) -> [TMLMascotAccessory] {
        all.first { $0.id == id }?.accessories ?? []
    }

    /// True when the accessory (or none) fits the mascot.
    public static func takes(_ id: TMLMascotId, _ accessory: TMLMascotAccessory?) -> Bool {
        guard let accessory else { return true }
        return accessories(for: id).contains(accessory)
    }
}
